"""Calculate monthly payroll from the supplied cleaning-service CSV files."""

import csv
import json
import re
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from pathlib import Path


DATASET = Path(__file__).resolve().parent / "dataset"
ZERO = Decimal("0")


def _read_csv(name: str) -> list[dict[str, str]]:
    with (DATASET / name).open(encoding="utf-8-sig", newline="") as handle:
        return list(csv.DictReader(handle))


def _number(value: str) -> Decimal | None:
    try:
        result = Decimal(value)
    except (InvalidOperation, ValueError, TypeError):
        return None
    return result if result.is_finite() else None


def _billing_month(day: date, weekday: int) -> tuple[int, int]:
    """A month starts on its first occurrence of the common payday weekday."""
    first = day.replace(day=1)
    start = first + timedelta(days=(weekday - first.weekday()) % 7)
    if day < start:
        first -= timedelta(days=1)
    return first.year, first.month


def _task_ids(value: str) -> tuple[str, ...] | None:
    # Missing opening/closing brackets are recoverable: the IDs are intact.
    value = value.strip()
    if not re.fullmatch(r"\[?\s*(?:\d+(?:\s*,\s*\d+)*)?\s*\]?", value):
        return None
    return tuple(re.findall(r"\d+", value))


def answer() -> dict[str, list[int]]:
    """Return salaries in ascending billing-month order, keyed by PESEL.

    The employee and task catalogs are authoritative. Unknown employee IDs
    cannot be linked reliably and are excluded; unknown tasks earn no bonus.
    Impossible dates have no uniquely recoverable replacement and are excluded.
    Duplicate timesheet payloads count once, regardless of their row IDs.

    salary_amount is a running monthly base-pay total, so it must not be summed.
    Both base pay and bonuses are instead recalculated from their source data.
    """
    employees: dict[str, Decimal] = {}
    for row in _read_csv("employees.csv"):
        rate = _number(row["hourly_rate"])
        pesel = row["PESEL"].strip()
        if re.fullmatch(r"\d{11}", pesel) and rate is not None and rate >= ZERO:
            employees[pesel] = rate

    task_pay: dict[str, Decimal] = {}
    for row in _read_csv("tasks.csv"):
        payment = _number(row["pay_per_completion"])
        if payment is not None and payment >= ZERO:
            task_pay[row["task_id"].strip()] = payment

    records = []
    seen = set()
    for row in _read_csv("timesheet.csv"):
        pesel = row["employee_id"].strip()
        if pesel not in employees:
            continue
        try:
            day = date.fromisoformat(row["date"].strip())
        except ValueError:
            continue

        hours = _number(row["hours_worked"])
        tasks = _task_ids(row["performed_tasks"])
        if hours is None or not ZERO <= hours <= Decimal("24"):
            continue
        if tasks is None:
            continue

        payload = tuple((key, value) for key, value in row.items() if key != "id")
        if payload in seen:
            continue
        seen.add(payload)

        bonus = sum((task_pay.get(task, ZERO) for task in tasks), ZERO)
        records.append((pesel, day, hours * employees[pesel] + bonus))

    if not records:
        return {pesel: [] for pesel in employees}

    weekday = min(day for _, day, _ in records).weekday()
    totals = defaultdict(lambda: ZERO)
    months = set()
    for pesel, day, amount in records:
        month = _billing_month(day, weekday)
        months.add(month)
        totals[pesel, month] += amount

    ordered_months = sorted(months)
    return {
        pesel: [
            int(totals[pesel, month].quantize(Decimal("1"), rounding=ROUND_HALF_UP))
            for month in ordered_months
        ]
        for pesel in employees
    }


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as handle:
        json.dump(answer(), handle, default=list, indent=2)
        handle.write("\n")
